 function comparison(){const rows=summaries(),s=examUI.session,current=rows.find(r=>r.result.attemptId===s?.resultRecord?.attemptId),previous=rows.find(r=>r.result.attemptId!==s?.resultRecord?.attemptId&&(!s?.resultRecord?.completedAt||r.result.completedAt<s.resultRecord.completedAt)&&r.edition?.examRound===s?.examRound&&r.edition?.examLevel===s?.examLevel);if(!current||!previous)return officialResultPage();const now=current.result.graded||{},old=previous.result.graded||{},changes=[['틀렸다가 맞힌 문제',current.entries.filter(e=>old[e.canonicalQuestionId]===false&&now[e.canonicalQuestionId]===true).length,'done'],['여전히 틀린 문제',current.entries.filter(e=>old[e.canonicalQuestionId]===false&&now[e.canonicalQuestionId]===false).length,'wrong'],['새로 틀린 문제',current.entries.filter(e=>old[e.canonicalQuestionId]===true&&now[e.canonicalQuestionId]===false).length,'current']];return `${header('재시험 결과','data-r3-aux-back="true"',false)}<div class="r3-inset"><small class="r3-overline">ROUND ${s.examRound} · 재응시</small><h1 class="r3-comparison-title">${scoreOf(previous)}점에서 ${scoreOf(current)}점으로,<br>${Math.abs(scoreOf(current)-scoreOf(previous))}점 ${scoreOf(current)>=scoreOf(previous)?'올랐어요':'변했어요'}</h1>${ladder(scoreOf(current),scoreOf(previous),s.examLevel)}<section class="r3-section">${heading('문항 변화')}${changes.map(([t,n,tone])=>`<div class="r3-tool-row"><span><b>${t}</b></span><b class="${tone==='wrong'?'r3-red':''}">${n}문항</b></div>`).join('')}</section><section class="r3-section">${heading('시대별 변화')}${officialResultEraAnalysis(s,'attempt').rows.map(r=>{const prior=officialResultEraAnalysis({entries:previous.entries,graded:old,answers:previous.result.answers,resultRecord:previous.result},'attempt').rows.find(p=>p.id===r.id);return `<div class="r3-change-row"><small>${r.name}</small><div class="progress"><i style="width:${r.accuracy||0}%"></i></div><b>${r.accuracy==null||prior?.accuracy==null?'—':(r.accuracy-prior.accuracy>=0?'+':'')+(r.accuracy-prior.accuracy)}</b></div>`;}).join('')}</section>${button('오답 다시 풀기','data-official-retry="true"')}</div>`;}
 officialExamHistoryPage=function(){let rows=summaries();const all=rows,pass=rows.filter(r=>r.certification.passed).length;if(recordFilter==='passed')rows=rows.filter(r=>r.certification.passed);else if(recordFilter!=='all')rows=rows.filter(r=>r.edition?.examLevel===recordFilter);return `<section class="official-exam-history">${header('시험 기록','data-official-results-back="true"',false)}${metrics([['응시',all.length,'회'],['합격',pass,'회'],['평균',all.length?Math.round(all.reduce((n,r)=>n+(scoreOf(r)||0),0)/all.length*10)/10:'—','점']])}<div class="r3-inset"><div class="r3-chips">${[['all','전체'],['심화','심화'],['기본','기본'],['passed','합격']].map(([id,t])=>`<button data-r3-record-filter="${id}" aria-pressed="${recordFilter===id}">${t}</button>`).join('')}</div><div class="r3-path-list">${rows.map(resultRow).join('')||empty('아직 시험 기록이 없어요','첫 시험에 출발해 보세요.',button('기출 출발하기','data-nav="exam-library"'))}</div></div></section>`;};
 officialRecordsPage=function(){const rows=summaries(),avg=recentAverage(),stats=periodLearning(meta(),'all'),best=rows.length?Math.max(...rows.map(r=>scoreOf(r)||0)):null;return `<section class="r3-records">${header('내 기록')}${rows.length?`<div class="r3-goal"><small class="r3-overline">ESTIMATED GRADE</small><h1>${avg==null?'학습 중':avg>=80?'1급':avg>=70?'2급':avg>=60?'3급':'합격 준비 중'} <small>최근 ${Math.min(3,rows.length)}회 평균 ${avg??'—'}점</small></h1>${ladder(avg)}</div>${metrics([['누적 풀이',stats.attempts,'문항'],['정답률',stats.accuracy??'—','%'],['응시',rows.length,'회'],['최고',best??'—','점']])}<section class="r3-section">${heading('점수 여정','<button class="r3-link" data-official-results-list="true">전체 기록</button>')}<div class="r3-path-list">${rows.slice(0,4).map(resultRow).join('')}</div></section><div class="r3-record-tools">${button('오답노트','data-nav="study"','secondary')}${button('취약점','data-r3-analysis="true"','secondary')}</div>`:empty('아직 여정을 시작하지 않았어요','기출 한 회차를 풀면 점수와 예상 등급,<br>시대별 약점이 이곳에 기록돼요.',button('첫 기출 출발하기','data-nav="exam-library"'))+`<section class="r3-section">${heading('추천 출발 코스')}<div class="r3-path-list"><button class="r3-path-row" data-nav="exam-library"><span class="r3-station done">1</span><span class="r3-row-copy"><b>최신 회차 시험 보기</b><small>80분 · 실제 기출</small></span></button><button class="r3-path-row" data-nav="ox"><span class="r3-station">2</span><span class="r3-row-copy"><b>OX로 가볍게 몸풀기</b><small>시대별 20문제</small></span></button></div></section>`}<details class="r3-learning-details"><summary>이야기 · 족보 · 학습 기록</summary>${oldRecords()}${oxRecordSection()}${recordsBeforeExamMemory()}</details></section>`;};
 oxHome=function(){const resume=activeOXSession(),wrong=oxCurrentWrongIds();return `<section class="ox-page ox-home">${header('OX 퀴즈')}<div class="r3-inset"><section class="r3-ox-today"><small>TODAY · 20 STOPS</small><h2>오늘의 20문제, 3분 여행</h2><div class="r3-ox-dots">${'<i></i>'.repeat(20)}</div>${button('출발 →','data-ox-start="daily" data-count="20"','white')}</section>${resume?`<button class="r3-continue accent" data-ox-resume="true"><span><b>진행 중인 퀴즈</b><small>${resume.index+1} / ${resume.questionIds.length}</small></span><b>이어하기 ›</b></button>`:''}<div class="r3-continue wrong"><span><b>틀린 OX ${wrong.length}문제</b><small>${wrong.length?'다시 만나며 기억해요':'복습할 문제가 없어요'}</small></span>${button('복습','data-ox-review="true" '+(wrong.length?'':'disabled'))}</div><section class="r3-section">${heading('시대별 정거장')}<div class="r3-path-list">${OX_ERAS.map(era=>{const row=oxStats(era.id),percent=row.total?Math.round(row.learned/row.total*100):0;return `<button class="r3-path-row" data-ox-era="${era.id}"><span class="r3-station ${percent===100?'done':percent?'soft':''}">${percent===100?'✓':percent+'%'}</span><span class="r3-row-copy"><b>${esc(era.name)}</b><small>${row.learned?`${row.learned} / ${row.total}문제 학습`:`${row.total}문제 · 아직 출발 전`}</small></span><span class="r3-chevron">›</span></button>`;}).join('')}</div></section><details class="r3-learning-details"><summary>복습할 시대 선택</summary><select data-ox-home-review-era>${oxReviewOptions(ox.homeReviewEra)}</select>${button('선택 시대 복습','data-ox-review="true" '+(oxCurrentWrongIds(ox.homeReviewEra).length?'':'disabled'))}</details></div></section>`;};
 oxQuiz=function(){const s=activeOXSession(),q=activeOXQuestion();if(!s||!q)return oxHome();const answered=Object.hasOwn(s.answers,q.id),selected=s.answers[q.id],correct=s.results[q.id];return `<section class="ox-page ox-play r3-ox-play"><header class="r3-play-header"><button class="r3-icon-button" data-ox-back="home" aria-label="퀴즈 나가기">${imageIcon('close')}</button><span><small>OX · ${esc(oxEra(q.eraId).shortName)}</small><b>${s.index+1} / ${s.questionIds.length}</b></span></header>${dots(s.questionIds.length,s.index,s.answers,s.questionIds)}<article class="r3-ox-question"><small class="r3-overline">STOP ${String(s.index+1).padStart(2,'0')}</small><h2>${esc(q.statement)}</h2><p>${esc(oxEra(q.eraId).name)}${q.sourceLabel?' · '+esc(q.sourceLabel):''}</p></article><div class="ox-answer-grid r3-ox-answers" role="group" aria-label="O 또는 X 선택">${[[true,'O','맞아요'],[false,'X','틀려요']].map(([value,label,t])=>`<button class="ox-answer ${label.toLowerCase()} ${answered?(q.answer===value?'right':selected===value?'wrong':'dimmed'):''}" data-ox-answer="${value}" ${answered?'disabled':''}><b>${label}</b><span>${t}</span></button>`).join('')}</div>${answered?`<section class="ox-feedback r3-feedback ${correct?'correct':'incorrect'}" aria-live="polite"><h2>${correct?'✓ 정답이에요':'× 정답은 '+(q.answer?'O':'X')+'예요'}</h2><p>${esc(q.explanation)}</p>${button(s.index===s.questionIds.length-1?'결과 확인':'다음 정거장 ›','data-ox-next="true"')}</section>`:''}</section>`;};
 oxResult=function(){const s=oxMeta().lastSession;if(!s?.summary)return oxHome();const sum=s.summary,wrong=s.questionIds.filter(id=>s.results[id]===false);let streak=0,best=0;for(const id of s.questionIds){streak=s.results[id]?streak+1:0;best=Math.max(best,streak);}return `<section class="ox-page ox-result">${header((s.eraId?oxEra(s.eraId).shortName+' ':'')+'OX 결과','data-ox-home="true"',false)}<div class="r3-inset"><small class="r3-overline">${sum.total} STOPS · 도착</small><div class="r3-score"><h1>${sum.correct}</h1><b class="r3-muted">/ ${sum.total} 정답</b></div><div class="r3-result-dots">${s.questionIds.map(id=>`<i class="${s.results[id]?'done':'wrong'}"></i>`).join('')}</div>${metrics([['정답률',sum.accuracy,'%'],['소요',oxDuration(sum.durationMs)],['연속 정답',best,'개']])}</div><section class="r3-result-band">${heading(wrong.length?'길을 잃은 '+wrong.length+'곳':'모든 정거장에 도착했어요!')}<div class="ox-result-wrongs">${wrong.map(id=>{const q=OX_BY_ID.get(id);return `<details class="r3-ox-wrong"><summary><span>${q.answer?'O':'X'}</span><div><small class="r3-red">STOP ${String(s.questionIds.indexOf(id)+1).padStart(2,'0')} · 내 답 ${s.answers[id]?'O':'X'}</small><p>${esc(q.statement)}</p></div></summary><p>${esc(q.explanation)}</p></details>`;}).join('')}</div></section><div class="r3-bottom-actions">${button('틀린 '+wrong.length+'곳 다시','data-ox-retry-wrong="true" '+(wrong.length?'':'disabled'),'secondary')}${button('다음 20문제','data-ox-start="daily" data-count="20"')}</div><button class="r3-link" data-ox-retry="true">같은 문제 다시 풀기</button></section>`;};
 function searchPage(){const query=searchText.trim().toLowerCase(),entries=query?OFFICIAL_EXAM_CATALOG.filter(e=>`${examSourceLabel(e)} ${officialQuestion(e.canonicalQuestionId)?.sourceQuestionText||''} ${officialVisibleExplanation(officialQuestion(e.canonicalQuestionId))}`.toLowerCase().includes(query)).slice(0,30):[];return `${header('기출 검색','data-r3-aux-back="true"',false)}<div class="r3-inset"><label class="r3-search-field">${imageIcon('search')}<input data-r3-search-input aria-label="기출 검색" value="${esc(searchText)}" placeholder="회차, 시대, 인물·사건 검색"><button data-r3-search-clear="true" aria-label="검색어 지우기">×</button></label><div id="r3-search-results">${query&&!entries.length?empty('관련 기출을 찾지 못했어요','회차 번호, 시대, 인물·사건 이름으로<br>다시 검색해 보세요.'):`<div class="official-question-list">${entries.map(e=>`<button data-official-single="${e.canonicalQuestionId}"><span><small>${examSourceLabel(e)}</small><b>${esc(officialQuestion(e.canonicalQuestionId)?.sourceQuestionText||'문제 보기')}</b></span>›</button>`).join('')}</div>`}</div></div>`;}
 const modalDialog=(title,copy,actions)=>`<div class="modal-overlay r3-overlay"><section class="modal r3-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${title}</h2><p>${copy}</p><div class="r3-dialog-actions">${actions}</div></section></div>`;
 modalHTML=function(){
  if(modal?.type==='r3-review-filter')return `<div class="modal-overlay r3-overlay"><section class="modal r3-sheet" role="dialog" aria-modal="true" aria-label="해설 문항 선택"><div class="official-sheet-handle"></div>${heading('해설 문항 선택','<button class="r3-icon-button" data-action="close" aria-label="닫기">×</button>')}<div class="r3-question-path">${(examUI.session?.entries||[]).map(e=>`<button class="${examUI.session.graded?.[e.canonicalQuestionId]?'done':'wrong'}" data-official-review="${e.canonicalQuestionId}">${e.sourceRecord.questionNumber}</button>`).join('')}</div></section></div>`;
  if(modal?.type==='r3-filter')return `<div class="modal-overlay r3-overlay"><section class="modal r3-sheet" role="dialog" aria-modal="true" aria-label="정렬·필터"><div class="official-sheet-handle"></div>${heading('정렬 · 필터','<button class="r3-link" data-r3-filter-reset="true">↻ 초기화</button>')}<small class="r3-muted">정렬</small>${[['latest','최신 회차순'],['oldest','오래된 회차순'],['pass-rate','합격률 낮은순']].map(([id,t])=>`<label class="r3-radio-row">${t}<input type="radio" name="r3-sort" value="${id}" ${examSort===id?'checked':''}></label>`).join('')}<small class="r3-muted">응시 상태</small><div class="r3-chips">${[['all','전체'],['idle','미응시'],['active','풀이 중'],['done','완료']].map(([id,t])=>`<button data-r3-exam-status="${id}" aria-pressed="${examStatus===id}">${t}</button>`).join('')}</div>${button('적용하기','data-r3-filter-apply="true"')}</section></div>`;
  if(modal?.type==='restart-episode'&&selectedEra==='goryeo')return modalDialog('고려 여정을 처음부터 할까요?','이야기 위치만 처음으로 돌아가요.<br>푼 기출과 오답 기록은 그대로 남아요.',button('취소','data-action="close"','secondary')+button('다시 시작','data-action="confirm-restart-episode"','danger'));
  if(modal?.type==='r3-pause')return modalDialog('잠시 쉬어가요',`남은 시간 ${officialFormatDuration(officialRemainingMs())} · ${examUI.session.index+1}번 정거장`,button('계속 풀기','data-official-timer-start="true"')+button('저장하고 나가기','data-r3-save-exit="true"','text'));
  if(modal?.type==='official-submit-confirm'){const n=officialUnansweredIndexes().length;return modalDialog(n?`${n}문제가 남았어요`:'시험을 제출할까요?',`지금 제출하면 바로 채점돼요.<br>미응답은 오답으로 처리돼요.`,button('계속 풀기','data-official-submit-cancel="true"','secondary')+button('제출하기','data-official-submit-confirm="true"')+(n?button('미응답 문제로 이동','data-official-submit-unanswered="true"','text'):''));}
  if(modal?.type==='r3-timeout')return modalDialog('도착! 시험 시간이 끝났어요','작성한 답안이 자동 제출됐어요.<br>바로 결과를 확인해 보세요.',button('결과 보기','data-r3-timeout-close="true"'));
  if(modal?.type==='official-question-sheet'){const s=examUI.session;if(!s)return '';return `<div class="modal-overlay official-question-sheet-overlay r3-overlay"><section class="modal official-question-sheet r3-sheet" role="dialog" aria-modal="true" aria-label="문제 지도"><div class="official-sheet-handle"></div>${heading('문제 지도',`<button class="r3-icon-button" data-official-question-list-close="button" aria-label="문제 목록 닫기">×</button>`)}${metrics([['응답',officialAnsweredIds(s).size],['미응답',officialUnansweredIndexes(s).length],['현재',s.index+1]])}<div class="official-question-number-grid">${s.entries.map((e,i)=>`<button class="official-question-number ${Number.isInteger(s.answers[e.canonicalQuestionId])?'answered':'unanswered'} ${s.index===i?'current':''}" data-official-question-jump="${i}" aria-label="${i+1}번 ${Number.isInteger(s.answers[e.canonicalQuestionId])?'답안 선택 완료':'미응답'}">${i+1}</button>`).join('')}</div><p class="r3-muted">● 응답　○ 미응답　● 현재</p>${button('답안 제출하기','data-r3-sheet-submit="true"')}<button class="r3-link" data-official-timer-restart="true">시험 처음부터</button></section></div>`;}
  return oldModal();
 };
 function loadingPage(){return `${header('기출문제')}<div class="r3-inset r3-skeleton" role="status" aria-label="기출문제를 불러오는 중"><i></i><i></i><i></i>${Array.from({length:6},()=>'<div><b></b><span><i></i><i></i></span></div>').join('')}</div>`;}
 function networkPage(){return `${header('기출문제')}<div class="r3-network-state">${empty('길이 끊겼어요','인터넷 연결을 확인한 뒤 다시 시도해 주세요.<br>풀던 답안은 기기에 저장돼 있어요.',button('↻ 다시 연결하기','data-r3-reconnect="true"'))}<button class="r3-link" data-r3-aux-back="true">현재 화면으로 돌아가기</button></div>`;}
 renderContent=function(){if(auxView==='loading')return loadingPage();if(auxView==='network')return networkPage();if(auxView==='analysis')return eraAnalysisPage();if(auxView==='comparison')return comparison();if(auxView==='search')return searchPage();return oldRenderContent();};
 (typeof window.addEventListener==='function'?window:document).addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
  if(d.nav||d.officialSingle||d.officialWeakEra||d.officialRetry||d.officialReview||d.officialStart||d.officialResultHome||d.oxStart)auxView=null;
  if(d.officialEra){eraSubset=d.r3EraSubset||null;}
  if(d.officialTab==='round')eraSubset=null;
  if(d.officialStart&&eraSubset&&examUI.tab==='era'){event.stopImmediatePropagation();const entries=officialSelectionEntries();if(d.officialStart==='exam')openOfficialExamCover(entries);else startOfficialSession(entries,d.officialStart);return;}
  if(d.officialStudyFrom&&eraSubset&&examUI.tab==='era'){event.stopImmediatePropagation();startOfficialSession(officialSelectionEntries(),'learn',{startQuestionId:d.officialStudyFrom,scope:'selection-from-list'});return;}
  if(d.officialReview&&modal?.type==='r3-review-filter')modal=null;
  if(d.r3Flag){event.stopImmediatePropagation();const flags=meta().rev3QuestionFlags||[];meta().rev3QuestionFlags=flags.includes(d.r3Flag)?flags.filter(id=>id!==d.r3Flag):[...flags,d.r3Flag];save();render();return;}
  if(d.r3Reconnect){event.stopImmediatePropagation();if(!failedImage){auxView=null;render();return;}auxView='loading';render();const probe=new Image();probe.onload=()=>{auxView=null;failedImage=null;render();};probe.onerror=()=>{auxView='network';render();};probe.src=failedImage;return;}
  if(d.r3Mode){event.stopImmediatePropagation();detailMode=d.r3Mode;render();return;}
  if(d.r3Begin){event.stopImmediatePropagation();const entries=officialSelectionEntries();if(detailMode==='learn')startOfficialSession(entries,'learn');else{openOfficialExamCover(entries);beginOfficialCover(examUI.cover.token);}return;}
  if(d.r3Filter){event.stopImmediatePropagation();modal={type:'r3-filter'};render();return;}
  if(d.r3FilterReset){event.stopImmediatePropagation();examSort='latest';examStatus='all';render();return;}
  if(d.r3ExamStatus){event.stopImmediatePropagation();examStatus=d.r3ExamStatus;render();return;}
  if(d.r3FilterApply){event.stopImmediatePropagation();modal=null;render();return;}
  if(d.r3RecordFilter){event.stopImmediatePropagation();recordFilter=d.r3RecordFilter;render();return;}
  if(d.r3Analysis){event.stopImmediatePropagation();auxView='analysis';render();window.scrollTo(0,0);return;}
  if(d.r3Comparison){event.stopImmediatePropagation();auxView='comparison';render();window.scrollTo(0,0);return;}
  if(d.r3AuxBack){event.stopImmediatePropagation();auxView=null;render();window.scrollTo(0,0);return;}
  if(d.r3Search){event.stopImmediatePropagation();auxView='search';searchText='';render();document.querySelector('[data-r3-search-input]')?.focus();return;}
  if(d.r3SearchClear){event.stopImmediatePropagation();searchText='';render();document.querySelector('[data-r3-search-input]')?.focus();return;}
  if(d.r3EraAll){event.stopImmediatePropagation();document.querySelector('.r3-era-covers')?.scrollIntoView({behavior:'smooth'});return;}
  if(d.r3SheetSubmit){event.stopImmediatePropagation();modal=null;requestOfficialSubmission();return;}
  if(d.r3Leave||d.r3SaveExit){event.stopImmediatePropagation();if(examUI.session?.mode==='exam'&&!examUI.session.graded)suspendOfficialActiveSession();examUI.view='home';screen='exam-library';modal=null;render();window.scrollTo(0,0);return;}
  if(d.r3TimeoutClose){event.stopImmediatePropagation();modal=null;render();return;}
  if(d.r3WrongReview){event.stopImmediatePropagation();const e=examUI.session?.entries.find(e=>examUI.session.graded?.[e.canonicalQuestionId]===false);if(e){examUI.session.reviewQuestionId=e.canonicalQuestionId;examUI.view='review';render();window.scrollTo(0,0);}return;}
  if(d.r3ReviewFilter){event.stopImmediatePropagation();modal= {type:'r3-review-filter'};render();return;}
 },true);
 document.addEventListener('change',event=>{if(event.target.matches('[name="r3-sort"]'))examSort=event.target.value;});
 function searchInput(event){if(!event.target.matches('[data-r3-search-input]'))return;searchText=event.target.value;if(event.isComposing)return;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(auxView!=='search')return;const pos=document.querySelector('[data-r3-search-input]')?.selectionStart;render();const input=document.querySelector('[data-r3-search-input]');input?.focus();if(pos!=null)input?.setSelectionRange(pos,pos);},180);}
 document.addEventListener('input',searchInput);document.addEventListener('compositionend',searchInput);
 // Pause remains owned by the existing timer; only its presentation changes.
 const beforeRender=render;
 render=function(){const s=examUI.session;if(s?.submissionReason==='TIME_EXPIRED'&&s.graded&&!s.readOnlyResult&&!timeoutSeen.has(s.attemptId)){timeoutSeen.add(s.attemptId);modal={type:'r3-timeout'};}if(examUI.view==='practice'&&screen==='exam-library'&&officialTimedSession()&&officialTimerState()==='PAUSED'&&!modal)modal={type:'r3-pause'};if(modal?.type==='r3-pause'&&officialTimerState()!=='PAUSED')modal=null;beforeRender();};
 document.addEventListener('error',event=>{if(event.target?.matches?.('.official-paper img')&&event.target.currentSrc){failedImage=event.target.currentSrc;auxView='network';render();}},true);
 globalThis.REV3_UI=Object.freeze({version:3,palette:{primary:'#2D5BE3',accent:'#F2A516',error:'#E5484D'},font:'Malgun Gothic',groupEras,eraEntries:subset=>presentationEraEntries(subset),views:{analysis:()=>{auxView='analysis';render();},comparison:()=>{auxView='comparison';render();},search:()=>{auxView='search';render();}},states:{loading:()=>{auxView='loading';render();},network:()=>{auxView='network';render();},clear:()=>{auxView=null;render();}}});
 examUI.replace({officialExamHome,officialExamListPage,officialRoundCard,officialPaperFigure,officialPracticePage,officialReviewPage,officialResultPage,officialExamHistoryPage,officialRecordsPage});
